const contexte_Normaliser_Les_Donn_es = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Contexte - Normaliser Les Données', parameters: { jsCode: '// Node Code justifié : les trois onglets arrivent tels que Google Sheets les rend (nombres « 2,5 » ou « -5 »,\n// booléens « oui » / « TRUE » / « VRAI », dates ISO, françaises ou numéros de série). Les normaliser, écarter\n// les lignes incomplètes en disant pourquoi et filtrer l\'historique récent demande des boucles et des\n// contrôles qu\'un node Set rendrait illisibles. Rien n\'est complété ni deviné : une donnée absente est signalée.\nconst C = $(\'CONFIGURATION\').first().json;\nconst brut = $input.first().json;\n\n// Version portable : tant que CONFIGURATION garde un « A_REMPLACER », s\'arrêter avant d\'envoyer un e-mail\n// à une adresse fictive ou des liens vers une autre instance.\nconst aRemplacer = Object.keys(C).filter(k => String(C[k]).includes(\'A_REMPLACER\'));\nif (aRemplacer.length) throw new Error(`CONFIGURATION à compléter avant la première exécution : remplacer « A_REMPLACER » dans ${aRemplacer.join(\', \')}`);\n\nconst texte = v => (v === null || v === undefined ? \'\' : String(v)).trim();\nconst nombre = v => {\n  const t = texte(v).replace(/−/g, \'-\').replace(\',\', \'.\');\n  return t !== \'\' && Number.isFinite(Number(t)) ? Number(t) : null;\n};\nconst vrai = v => [\'oui\', \'true\', \'vrai\', \'yes\', \'1\', \'x\'].includes(texte(v).toLowerCase());\nconst liste = v => texte(v).split(/[;,]/).map(s => s.trim()).filter(Boolean);\nconst lignes = v => (Array.isArray(v) ? v : []).filter(r => r && Object.keys(r).some(k => k !== \'row_number\' && texte(r[k]) !== \'\'));\n\nconst aujourdHui = new Intl.DateTimeFormat(\'sv-SE\', { timeZone: \'Europe/Paris\' }).format(new Date());\nconst jourSemaine = new Intl.DateTimeFormat(\'fr-FR\', { weekday: \'long\', timeZone: \'Europe/Paris\' }).format(new Date());\nconst problemes = [];\n\n// ---------- Preferences (Cle / valeur) ----------\nconst prefs = {};\nfor (const r of lignes(brut.preferences)) {\n  const cle = texte(r.Cle ?? r.cle ?? r[\'Clé\'] ?? r.cle_ ?? Object.values(r)[0]);\n  if (cle) prefs[cle] = texte(r.valeur ?? r.Valeur ?? Object.values(r)[1]);\n}\nconst ville = prefs.ville_defaut || \'\';\nif (!ville) problemes.push(\'« ville_defaut » absente de l\u2019onglet Preferences : impossible de savoir où récupérer la météo\');\nconst historiqueJours = Number.isInteger(nombre(prefs.historique_jours)) && nombre(prefs.historique_jours) >= 0\n  ? nombre(prefs.historique_jours) : C.historiqueJoursParDefaut;\nconst preferences = {\n  ville,\n  stylePrefere: prefs.style_prefere || \'\',\n  niveauFroid: prefs.niveau_froid || \'\',\n  sensibilitePluie: (prefs.sensibilite_pluie || \'moyenne\').toLowerCase(),\n  sensibiliteFroid: (prefs.sensibilite_froid || \'moyenne\').toLowerCase(),\n  tenueBureau: prefs.tenue_bureau || \'\',\n  historiqueJours,\n  autoriserReutilisationPieces: prefs.autoriser_reutilisation_pieces === undefined ? true : vrai(prefs.autoriser_reutilisation_pieces),\n  perimetreCatalogue: prefs.perimetre_catalogue || \'\',\n};\n\n// ---------- Vetements ----------\nconst CATEGORIES = [\'haut\', \'maille\', \'bas\', \'couche_externe\', \'chaussures\', \'accessoire\'];\nconst catalogue = [];\nconst exclus = [];\nconst vus = new Set();\nfor (const r of lignes(brut.vetements)) {\n  const id = texte(r.id).toUpperCase();\n  if (!vrai(r.actif)) continue; // pièce désactivée volontairement : pas une anomalie\n  const p = {\n    id, nom: texte(r.nom), categorie: texte(r.categorie).toLowerCase(), sous_categorie: texte(r.sous_categorie),\n    couleur: texte(r.couleur), matiere: texte(r.matiere), saison: liste(r.saison),\n    tempMin: nombre(r.temp_min_C), tempMax: nombre(r.temp_max_C),\n    pluie: vrai(r.pluie_adapte), vent: vrai(r.vent_adapte),\n    style: liste(r.style), occasion: liste(r.occasion),\n    image_url: /^https:\\/\\//i.test(texte(r.image_url)) ? texte(r.image_url) : \'\',\n    url_source: texte(r.url_source), notes: texte(r.notes),\n  };\n  const manque = [];\n  if (!id) manque.push(\'id\');\n  if (!p.nom) manque.push(\'nom\');\n  if (!CATEGORIES.includes(p.categorie)) manque.push(`categorie « ${p.categorie || \'vide\'} » inconnue`);\n  if (p.tempMin === null || p.tempMax === null) manque.push(\'temp_min_C / temp_max_C\');\n  else if (p.tempMin > p.tempMax) manque.push(\'temp_min_C supérieure à temp_max_C\');\n  if (id && vus.has(id)) manque.push(\'id en double\');\n  if (manque.length) { exclus.push({ id: id || `ligne ${r.row_number ?? \'?\'}`, raison: manque.join(\', \') }); continue; }\n  vus.add(id);\n  catalogue.push(p);\n}\n// Une tenue part tous les jours où la météo est connue : une catégorie manquante devient un point\n// d\'attention de la tenue. Sans aucune pièce, rien ne peut être proposé sans inventer : incident.\nif (!catalogue.length) {\n  throw new Error(`Onglet Vetements inutilisable : aucune pièce active et complète${exclus.length ? ` (${exclus.length} ligne(s) écartée(s), par exemple ${exclus[0].id} : ${exclus[0].raison})` : \'\'}`);\n}\n\n// ---------- Historique_Tenues (tenues réellement validées) ----------\nfunction dateIso(v) {\n  const t = texte(v);\n  let m;\n  if ((m = t.match(/^(\\d{4})-(\\d{2})-(\\d{2})/))) return `${m[1]}-${m[2]}-${m[3]}`;\n  if ((m = t.match(/^(\\d{1,2})\\/(\\d{1,2})\\/(\\d{4})/))) return `${m[3]}-${m[2].padStart(2, \'0\')}-${m[1].padStart(2, \'0\')}`;\n  const serie = nombre(t);\n  if (serie !== null && serie > 30000 && serie < 80000) return new Date(Date.UTC(1899, 11, 30) + serie * 864e5).toISOString().slice(0, 10);\n  return \'\';\n}\nconst ids = v => texte(v).toUpperCase().split(/[;,+\\s]+/).filter(x => /^[A-Z0-9_-]+$/.test(x));\nconst limite = new Date(Date.parse(aujourdHui + \'T00:00:00Z\') - historiqueJours * 864e5).toISOString().slice(0, 10);\nconst historiqueRecent = [];\nfor (const r of lignes(brut.historique)) {\n  const date = dateIso(r.date);\n  if (!date) { exclus.push({ id: `historique ligne ${r.row_number ?? \'?\'}`, raison: `date illisible « ${texte(r.date)} »` }); continue; }\n  if (texte(r.tenue_acceptee) && !vrai(r.tenue_acceptee)) continue;\n  if (date < limite || date > aujourdHui) continue;\n  const structure = [...ids(r.haut_id), ...ids(r.couche_externe_id), ...ids(r.bas_id), ...ids(r.chaussures_id)];\n  historiqueRecent.push({\n    date, pieces: [...structure, ...ids(r.accessoires_ids)], cle: [...new Set(structure)].sort().join(\'+\'),\n    combinaison_hash: texte(r.combinaison_hash),\n  });\n}\nhistoriqueRecent.sort((a, b) => b.date.localeCompare(a.date));\n\n// ---------- Règles météo personnalisées (Preferences > CONFIGURATION) ----------\nconst facteurPluie = { \'élevée\': [0.75, 0.4], elevee: [0.75, 0.4], faible: [1.5, 2] }[preferences.sensibilitePluie] || [1, 1];\nconst decalageRessentiC = { \'élevée\': -2, elevee: -2, faible: 2 }[preferences.sensibiliteFroid] ?? 0;\n\nreturn [{\n  json: {\n    pret: problemes.length === 0, // seul blocage possible : la ville, donc la météo\n    etape: \'météo\',\n    raison: problemes.join(\' ; \'),\n    date: aujourdHui,\n    jourSemaine,\n    estJourOuvre: ![\'samedi\', \'dimanche\'].includes(jourSemaine),\n    preferences,\n    catalogue,\n    exclus,\n    historiqueRecent,\n    seuils: {\n      pluieProbaPct: Math.round(C.seuilPluiePct * facteurPluie[0]),\n      pluieMm: Math.round(C.seuilPluieMm * facteurPluie[1] * 10) / 10,\n      ventKmh: C.seuilVentKmh, rafalesKmh: C.seuilRafalesKmh,\n      ecartModulableC: C.ecartModulableC, decalageRessentiC,\n    },\n    regles: {\n      toleranceFroidC: C.toleranceFroidC, toleranceFroidBasC: C.toleranceFroidBasC, toleranceChaudC: C.toleranceChaudC,\n      seuilVesteC: C.seuilVesteC, seuilVentFroidC: C.seuilVentFroidC, differenceMinPieces: C.differenceMinPieces,\n      candidatsParProfil: C.candidatsParProfil, autoriserReutilisationPieces: preferences.autoriserReutilisationPieces,\n    },\n  },\n}];\n' }, position: [1968, 384] }
});

