const email_Composer_Le_HTML = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Email - Composer Le HTML', parameters: { jsCode: '// ---------- Rendu commun : e-mail du matin et pages de validation ----------\n// Mise en page en tableaux et styles en ligne : c\'est ce que les clients e-mail (Gmail, Outlook, Apple Mail)\n// affichent de façon fiable. Les pages de validation réutilisent les mêmes cartes pour rester cohérentes.\nconst POLICE = "-apple-system,BlinkMacSystemFont,\'Segoe UI\',\'Helvetica Neue\',Helvetica,Arial,sans-serif";\nconst TITRE = "Georgia,\'Times New Roman\',serif";\nconst T = { fond: \'#F3F1EC\', carte: \'#FFFFFF\', bord: \'#E7E3DA\', texte: \'#1B1B1A\', doux: \'#6E6A63\', pale: \'#9C978D\', encre: \'#1B1B1A\' };\nconst PROFIL = {\n  equilibree: { encre: \'#2F4A6B\', fond: \'#E9EEF4\' },\n  legere: { encre: \'#4D6A48\', fond: \'#EAF0E6\' },\n  protection: { encre: \'#8A4A2B\', fond: \'#F5EAE3\' },\n};\nconst COULEURS = {\n  blanc: \'#F7F6F2\', \'écru\': \'#EFE9DC\', noir: \'#1E1E1E\', marine: \'#1F2B45\', gris: \'#A3A29D\', \'gris clair\': \'#C9C8C3\',\n  \'gris chiné\': \'#A9A8A2\', \'gris foncé\': \'#4B4B49\', \'bleu ciel\': \'#BCD3E8\', bleu: \'#3B5B8C\', \'bleu foncé\': \'#2B3A56\',\n  beige: \'#D9C9AB\', camel: \'#BF9567\', marron: \'#5C4033\', kaki: \'#6E6B4B\', olive: \'#6B6B3A\', vert: \'#55624A\',\n  bordeaux: \'#6B2232\', rouge: \'#B3262E\',\n};\n\nconst esc = v => String(v ?? \'\').replace(/[&<>"\']/g, ch => ({ \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\', "\'": \'&#39;\' }[ch]));\nconst deg = n => `${Math.round(n)}°`;\nconst pct = n => `${Math.round(n)} %`;\nfunction teinte(couleur) {\n  const cl = String(couleur || \'\').toLowerCase().trim();\n  return COULEURS[cl] || COULEURS[cl.split(/\\s+/)[0]] || \'#CFCBC2\';\n}\nfunction estClair(hex) {\n  const n = parseInt(hex.slice(1), 16);\n  return 0.299 * (n >> 16) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255) > 150;\n}\nfunction dateLongue(iso) {\n  const t = new Intl.DateTimeFormat(\'fr-FR\', { weekday: \'long\', day: \'numeric\', month: \'long\', timeZone: \'UTC\' }).format(new Date(iso + \'T12:00:00Z\'));\n  return t.charAt(0).toUpperCase() + t.slice(1);\n}\n\n// Photo si image_url est renseignée (https uniquement), sinon vignette couleur : rien n\'est inventé.\nfunction vignette(p) {\n  if (p.image_url) {\n    return `<img src="${esc(p.image_url)}" alt="${esc(p.nom)}" width="150" style="display:block;width:100%;max-width:150px;height:auto;border:0;border-radius:12px;background:#EEEBE4">`;\n  }\n  const fond = teinte(p.couleur);\n  const clair = estClair(fond);\n  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:150px;border-collapse:separate;background:${fond};border-radius:12px;${clair ? \'border:1px solid #E2DED5;\' : \'\'}">`\n    + `<tr><td align="center" valign="middle" height="132" style="height:132px;padding:0 10px;font-family:${POLICE};color:${clair ? \'#4A4743\' : \'#F3F1EC\'}">`\n    + `<div style="font-size:11px;line-height:15px;font-weight:600;letter-spacing:1.8px;text-transform:uppercase">${esc(p.sous_categorie)}</div>`\n    + `<div style="width:18px;height:1px;background:${clair ? \'#4A4743\' : \'#F3F1EC\'};opacity:.45;margin:9px auto"></div>`\n    + `<div style="font-size:10px;line-height:14px;letter-spacing:1.4px;text-transform:uppercase;opacity:.8">${esc(p.couleur)}</div>`\n    + \'</td></tr></table>\';\n}\n\nfunction grillePieces(tenue) {\n  const principales = tenue.pieces.filter(p => p.couche !== \'accessoire\');\n  const lignes = [];\n  for (let i = 0; i < principales.length; i += 3) lignes.push(principales.slice(i, i + 3));\n  const cellule = p => `<td width="33%" valign="top" style="width:33%;padding:0 6px 18px">${vignette(p)}`\n    + `<div style="font-family:${POLICE};font-size:10px;line-height:14px;letter-spacing:1.4px;text-transform:uppercase;color:${T.pale};margin-top:10px">${esc(p.coucheLibelle)}</div>`\n    + `<div style="font-family:${POLICE};font-size:13px;line-height:18px;color:${T.texte};margin-top:2px">${esc(p.nom)}</div>`\n    + `<div style="font-family:${POLICE};font-size:11px;line-height:16px;color:${T.doux};margin-top:2px">${esc(p.matiere)}</div></td>`;\n  const html = lignes.map(l => `<tr>${l.map(cellule).join(\'\')}${\'<td width="33%" style="width:33%"></td>\'.repeat(3 - l.length)}</tr>`).join(\'\');\n  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:18px">${html}</table>`;\n}\n\nfunction accessoires(tenue) {\n  const acc = tenue.pieces.filter(p => p.couche === \'accessoire\');\n  if (!acc.length) return \'\';\n  const pastille = p => `<span style="display:inline-block;margin:0 14px 6px 0;font-family:${POLICE};font-size:12px;line-height:18px;color:${T.doux};white-space:nowrap">`\n    + `<span style="display:inline-block;width:9px;height:9px;border-radius:9px;background:${teinte(p.couleur)};border:1px solid #D9D4CA;vertical-align:-1px;margin-right:6px"></span>${esc(p.nom)}</span>`;\n  return `<div style="margin:0 0 14px"><span style="font-family:${POLICE};font-size:10px;letter-spacing:1.4px;text-transform:uppercase;color:${T.pale};margin-right:10px">Accessoires</span>${acc.map(pastille).join(\'\')}</div>`;\n}\n\nfunction bouton(lien, libelle, couleur = T.encre) {\n  return `<table role="presentation" cellpadding="0" cellspacing="0" style="margin-top:6px"><tr><td style="border-radius:999px;background:${couleur}">`\n    + `<a href="${esc(lien)}" style="display:inline-block;padding:13px 26px;font-family:${POLICE};font-size:14px;font-weight:600;line-height:18px;color:#FFFFFF;text-decoration:none;border-radius:999px">${esc(libelle)}</a>`\n    + \'</td></tr></table>\';\n}\n\n// Tenue « au plus proche » : ce qu\'aucune pièce du catalogue ne permet de respecter aujourd\'hui, dit clairement.\nfunction attention(tenue) {\n  const points = tenue.pointsAttention || [];\n  if (!points.length) return \'\';\n  return `<div style="margin:0 0 18px;padding:12px 14px;border-radius:12px;background:#FBF3E4;font-family:${POLICE};font-size:13px;line-height:20px;color:#6B4E16">`\n    + `<b style="font-weight:600">À savoir</b> — aucune combinaison de ton catalogue ne coche toutes les règles aujourd\u2019hui :`\n    + `<ul style="margin:6px 0 0;padding-left:18px">${points.map(p => `<li>${esc(p)}</li>`).join(\'\')}</ul></div>`;\n}\n\n// Carte d\'une tenue. options.lien : bouton de validation ; options.pied : HTML libre sous la carte.\nfunction carteTenue(tenue, meteo, options = {}) {\n  const pal = PROFIL[tenue.profil] || PROFIL.equilibree;\n  const fen = meteo.fenetre;\n  const action = options.lien ? bouton(options.lien, \'Choisir cette tenue →\', pal.encre)\n    : options.sansAction ? \'\' : `<div style="font-family:${POLICE};font-size:12px;color:${T.pale}">Validation indisponible aujourd\u2019hui (enregistrement de la proposition en échec).</div>`;\n  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${T.carte};border:1px solid ${T.bord};border-radius:18px;border-collapse:separate;margin:0 0 18px">`\n    + `<tr><td style="padding:26px 26px 24px">`\n    + `<span style="display:inline-block;padding:5px 11px;border-radius:999px;background:${pal.fond};color:${pal.encre};font-family:${POLICE};font-size:11px;font-weight:600;letter-spacing:1.4px;text-transform:uppercase">Tenue ${tenue.numero} · ${esc(tenue.profilLibelle)}</span>`\n    + `<div style="font-family:${TITRE};font-size:23px;line-height:30px;color:${T.texte};margin-top:12px">${esc(tenue.nom)}</div>`\n    + (tenue.origine && tenue.origine !== \'ia\' ? `<div style="font-family:${POLICE};font-size:11px;line-height:16px;letter-spacing:1.4px;text-transform:uppercase;color:${T.pale};margin-top:4px">Composée par les règles du workflow, sans IA</div>` : \'\')\n    + `<div style="font-family:${POLICE};font-size:12px;line-height:18px;color:${T.doux};margin-top:4px">Pour ${deg(fen.tMin)} → ${deg(fen.tMax)} · ressenti dès ${deg(fen.ressentiMin)} · pluie ${pct(fen.pluieProbaMax)} · rafales ${fen.rafalesMax} km/h</div>`\n    + grillePieces(tenue)\n    + accessoires(tenue)\n    + `<div style="font-family:${POLICE};font-size:14px;line-height:22px;color:${T.texte};margin:0 0 10px">${esc(tenue.explication)}</div>`\n    + `<div style="font-family:${POLICE};font-size:13px;line-height:20px;color:${T.doux};margin:0 0 18px;padding-left:12px;border-left:2px solid ${pal.fond}"><b style="color:${pal.encre};font-weight:600">Météo</b> — ${esc(tenue.justificationMeteo)}</div>`\n    + attention(tenue)\n    + action + (options.pied || \'\')\n    + \'</td></tr></table>\';\n}\n\n// Node Code justifié : gabarit HTML de l\'e-mail (boucles sur les tenues, les pièces et les périodes,\n// échappement de chaque valeur venue du Google Sheets ou du modèle). Le rendu commun ci-dessus est\n// partagé avec les pages de validation pour garder une seule charte.\nconst C = $(\'CONFIGURATION\').first().json;\nconst ctx = $(\'Contexte - Normaliser Les Données\').first().json;\nconst meteo = $(\'Exécuter - Prévisions Météo\').first().json.meteo;\nconst generation = $(\'Exécuter - Générer Les Tenues\').first().json;\nconst propositions = $input.first().json.propositions;\nconst j = meteo.journee;\nconst fen = meteo.fenetre;\n\nconst periode = p => `<td width="33%" valign="top" style="width:33%;padding:14px 8px 0 0">`\n  + `<div style="font-family:${POLICE};font-size:10px;letter-spacing:1.4px;text-transform:uppercase;color:${T.pale}">${esc(p.nom)}</div>`\n  + `<div style="font-family:${POLICE};font-size:15px;line-height:22px;color:${T.texte};margin-top:4px">${p.icone} ${deg(p.tMin)} → ${deg(p.tMax)}</div>`\n  + `<div style="font-family:${POLICE};font-size:12px;line-height:18px;color:${T.doux}">pluie ${pct(p.pluieProbaMax)} · vent ${p.ventMax} km/h</div></td>`;\nconst alerte = a => `<span style="display:inline-block;margin:0 6px 6px 0;padding:6px 11px;border-radius:999px;background:${T.fond};font-family:${POLICE};font-size:12px;line-height:16px;color:${T.texte}">${a.icone} ${esc(a.texte)}</span>`;\n\nconst blocMeteo = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${T.carte};border:1px solid ${T.bord};border-radius:18px;border-collapse:separate;margin:0 0 22px">`\n  + `<tr><td style="padding:24px 26px">`\n  + `<div style="font-family:${POLICE};font-size:11px;letter-spacing:2px;text-transform:uppercase;color:${T.pale}">Météo · ${esc(meteo.ville)}</div>`\n  + `<table role="presentation" cellpadding="0" cellspacing="0" style="margin-top:10px"><tr>`\n  + `<td valign="middle" style="font-size:42px;line-height:48px;padding-right:14px">${j.icone}</td>`\n  + `<td valign="middle"><div style="font-family:${TITRE};font-size:38px;line-height:42px;color:${T.texte}">${deg(j.tMin)}<span style="color:${T.pale}"> / </span>${deg(j.tMax)}</div>`\n  + `<div style="font-family:${POLICE};font-size:13px;line-height:20px;color:${T.doux}">${esc(j.description)} · ressenti ${deg(j.ressentiMin)} → ${deg(j.ressentiMax)}</div></td>`\n  + `</tr></table>`\n  + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:4px;border-top:1px solid ${T.bord}"><tr>${meteo.periodes.map(periode).join(\'\')}</tr></table>`\n  + `<div style="margin-top:16px">${meteo.alertes.map(alerte).join(\'\')}</div>`\n  + `<div style="font-family:${POLICE};font-size:12px;line-height:19px;color:${T.doux};margin-top:6px">${esc(meteo.resume)} Départ à ${meteo.sorties[0].heure} h : ressenti ${deg(meteo.sorties[0].ressenti)} ; retour à ${meteo.sorties[1].heure} h : ressenti ${deg(meteo.sorties[1].ressenti)}.</div>`\n  + \'</td></tr></table>\';\n\nconst n = propositions.length;\nconst pourquoi = generation.erreurGemini ? \'Gemini était indisponible ce matin\' : \'Aucune proposition de Gemini ne passait les contrôles ce matin\';\nconst intro = generation.origine === \'au plus proche\'\n  ? `${pourquoi} et aucune combinaison de ton catalogue ne respecte toutes les règles : voici la plus proche, avec ce qu\u2019il faut savoir.`\n  : generation.origine === \'regles\'\n    ? `${pourquoi} : ${n === 1 ? \'cette tenue a été composée\' : `ces ${n === 3 ? \'trois\' : n} tenues ont été composées`} directement par les règles du workflow, avec ton catalogue.`\n    : n === 3 ? \'Trois tenues composées avec ton catalogue, de la plus polyvalente à la plus protectrice.\'\n      : `${n === 1 ? \'Une seule tenue passe\' : `Seules ${n} tenues passent`} tous les contrôles météo et variété aujourd\u2019hui : rien n\u2019a été ajouté pour compléter la sélection.`;\nconst cartes = propositions.map(p => carteTenue(p.tenue, meteo, { lien: p.lien })).join(\'\');\nconst ecartees = generation.rejets.length;\nconst expire = propositions.find(p => p.expireLe)?.expireLe;\n\nconst html = `<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">`\n  + `<meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Météo Dressing</title></head>`\n  + `<body style="margin:0;padding:0;background:${T.fond}">`\n  + `<div style="display:none;max-height:0;overflow:hidden;opacity:0">${deg(fen.tMin)} → ${deg(fen.tMax)} à ${esc(meteo.ville)} · ${esc(meteo.alertes.map(a => a.texte).join(\' · \'))}</div>`\n  + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${T.fond}"><tr><td align="center" style="padding:28px 14px 40px">`\n  + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px">`\n  + `<tr><td style="padding:0 6px 22px">`\n  + `<div style="font-family:${POLICE};font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:${T.texte}">Météo Dressing${C.env === \'production\' ? \'\' : \' · test\'}</div>`\n  + `<div style="font-family:${TITRE};font-size:30px;line-height:38px;color:${T.texte};margin-top:8px">${esc(dateLongue(ctx.date))}</div>`\n  + `<div style="font-family:${POLICE};font-size:14px;line-height:21px;color:${T.doux};margin-top:6px">${esc(intro)}</div>`\n  + `</td></tr><tr><td>${blocMeteo}${cartes}</td></tr>`\n  + `<tr><td style="padding:8px 6px 0;font-family:${POLICE};font-size:11px;line-height:18px;color:${T.pale}">`\n  + `Composées uniquement à partir des ${ctx.catalogue.length} pièces actives de ton <a href="${esc(C.classeurUrl)}" style="color:${T.doux}">catalogue</a>`\n  + `${ecartees ? ` · ${ecartees} proposition${ecartees > 1 ? \'s\' : \'\'} écartée${ecartees > 1 ? \'s\' : \'\'} par les contrôles automatiques (détail dans LOGS)` : \'\'}.<br>`\n  + `Plages de confort indicatives · météo ${esc(meteo.source)} · modèles à vérifier sur uniqlo.com.`\n  + `${expire ? `<br>Liens de validation valables jusqu\u2019au ${esc(expire.slice(8, 10) + \'/\' + expire.slice(5, 7))} inclus ; une nouvelle validation le même jour remplace la précédente.` : \'\'}`\n  + \'</td></tr></table></td></tr></table></body></html>\';\n\nconst alertesSujet = [meteo.conditions.pluie ? \'pluie\' : \'\', meteo.conditions.vent ? \'vent\' : \'\'].filter(Boolean).join(\', \');\nconst sujet = `${C.env === \'production\' ? \'\' : \'[TEST] \'}${j.icone} ${n} tenue${n > 1 ? \'s\' : \'\'} pour ${dateLongue(ctx.date).toLowerCase()} · ${deg(fen.tMin)} → ${deg(fen.tMax)}${alertesSujet ? \', \' + alertesSujet : \'\'}`;\n\nreturn [{ json: { sujet, html } }];\n' }, position: [5328, 320] }
});

